package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct { // 01 SALES-REC, 12 bytes
	SrId    string          // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

type TierTable struct { // 01 TIER-TABLE
	TierEntry struct { // group
		TierLimit decimal.Decimal // PIC 9(6)V99
		TierRate  decimal.Decimal // PIC 9V99
	}
}

// Standalone working-storage items
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsIdx int64 = 0        // PIC 9
var WsTier int64 = 0       // PIC 9
var WsComm decimal.Decimal // PIC 9(6)V99
var WsTotal decimal.Decimal // PIC 9(9)V99
var WsCount int64 = 0         // PIC 9(3)
var WsSalesEd string          // PIC ZZZ,ZZ9.99 len=10
var WsRateEd string           // PIC 9.99 len=4
var WsCommEd string           // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string          // PIC ZZZ,ZZZ,ZZ9.99 len=14

// File record (current)
var SrId string
var SrSales decimal.Decimal

// Tier table 1-based (index 1..4)
var tierLimits [5]decimal.Decimal
var tierRates [5]decimal.Decimal

// Input lines for SALES-FILE
var salesLines []string
var salesIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func parseSales(field string) decimal.Decimal {
	var b strings.Builder
	for _, ch := range field {
		if ch >= '0' && ch <= '9' {
			b.WriteRune(ch)
		} else if ch == ' ' {
			b.WriteByte('0')
		} else {
			b.WriteByte('0')
		}
	}
	s := b.String()
	if s == "" {
		s = "0"
	}
	var n int64
	for _, ch := range s {
		n = n*10 + int64(ch-'0')
	}
	return decimal.New(n, -2)
}

func formatEdited(val decimal.Decimal, picInt string, nIntDigits int) string {
	a := val.Abs()
	scaled := a.Shift(2).Truncate(0).IntPart()
	intPart := scaled / 100
	fracPart := scaled % 100
	if fracPart < 0 {
		fracPart = -fracPart
	}
	mod := int64(1)
	for i := 0; i < nIntDigits; i++ {
		mod *= 10
	}
	// low-order truncation
	if intPart < 0 {
		intPart = -intPart
	}
	intPart = intPart % mod
	digits := fmt.Sprintf("%0*d", nIntDigits, intPart)
	first := nIntDigits - 1
	for i := 0; i < nIntDigits; i++ {
		if digits[i] != '0' {
			first = i
			break
		}
	}
	var sb strings.Builder
	digitIdx := 0
	for _, ch := range picInt {
		if ch == ',' {
			if first < digitIdx {
				sb.WriteByte(',')
			} else {
				sb.WriteByte(' ')
			}
		} else {
			if digitIdx < first {
				if ch == 'Z' {
					sb.WriteByte(' ')
				} else {
					sb.WriteByte(digits[digitIdx])
				}
			} else {
				sb.WriteByte(digits[digitIdx])
			}
			digitIdx++
		}
	}
	sb.WriteByte('.')
	sb.WriteString(fmt.Sprintf("%02d", fracPart))
	return sb.String()
}

func MainPara() {
	InitPara()
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		os.Exit(1)
	}
	scanner := bufio.NewScanner(f)
	// allow long lines
	const maxCap = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCap)
	salesLines = nil
	salesIdx = 0
	for scanner.Scan() {
		line := scanner.Text()
		salesLines = append(salesLines, line)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		f.Close()
		os.Exit(1)
	}
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	f.Close()
	SummaryPara()
}

func InitPara() {
	tierLimits[1] = decimal.New(100000, -2)
	tierRates[1] = decimal.New(250, -2)
	tierLimits[2] = decimal.New(500000, -2)
	tierRates[2] = decimal.New(400, -2)
	tierLimits[3] = decimal.New(2000000, -2)
	tierRates[3] = decimal.New(550, -2)
	tierLimits[4] = decimal.New(99999999, -2)
	tierRates[4] = decimal.New(725, -2)
}

func ReadPara() {
	if salesIdx >= len(salesLines) {
		WsEofFlag = "Y"
		return
	}
	line := salesLines[salesIdx]
	salesIdx++
	if len(line) < 12 {
		line += strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	SrId = line[0:4]
	SrSales = parseSales(line[4:12])
}

func ProcessPara() {
	WsTier = 0
	for WsIdx = 1; !(WsIdx > 4 || WsTier > 0); WsIdx++ {
		if SrSales.Cmp(tierLimits[WsIdx]) <= 0 {
			WsTier = WsIdx
		}
	}
	rate := tierRates[WsTier]
	prod := SrSales.Mul(rate)
	divided := prod.Shift(-2)
	rounded := divided.Round(2)
	scaled := rounded.Shift(2).Truncate(0).IntPart()
	mod := int64(100000000)
	var stored int64
	if scaled >= 0 {
		stored = scaled % mod
	} else {
		stored = -((-scaled) % mod)
	}
	WsComm = decimal.New(stored, -2)
	newTotal := WsTotal.Add(WsComm).Truncate(2)
	scaledT := newTotal.Shift(2).Truncate(0).IntPart()
	modT := int64(100000000000)
	var storedT int64
	if scaledT >= 0 {
		storedT = scaledT % modT
	} else {
		storedT = -((-scaledT) % modT)
	}
	WsTotal = decimal.New(storedT, -2)
	WsCount = (WsCount + 1) % 1000
	WsSalesEd = formatEdited(SrSales, "ZZZ,ZZ9", 6)
	WsRateEd = formatEdited(rate, "9", 1)
	WsCommEd = formatEdited(WsComm, "ZZZ,ZZ9", 6)
	tierStr := fmt.Sprintf("%d", WsTier%10)
	line := SrId + " T" + tierStr + " " + WsSalesEd + " " + WsRateEd + "% " + WsCommEd
	os.Stdout.WriteString(line + "\n")
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZZ,ZZZ,ZZ9", 9)
	countStr := fmt.Sprintf("%03d", WsCount)
	line := "REPS: " + countStr + " TOTAL: " + WsTotalEd
	os.Stdout.WriteString(line + "\n")
}

func main() {
	WsEofFlag = "N"
	WsComm = decimal.NewFromInt(0)
	WsTotal = decimal.NewFromInt(0)
	MainPara()
}
